{"type": "item.started", "item": {"id": "item_12", "type": "command_execution", "command": "/bin/bash -lc "curl -fsSL https://docs.mcpjam.com/cli/reference.md -o /workspace/mcp-eval/cli-reference.md && rg -n -i 'usage|credits|billing|cost' /workspace/mcp-eval/cli-reference.md | head -60; curl -fsSL https://docs.mcpjam.com/inspector/evals.md -o /workspace/mcp-eval/evals.md && rg -n -i 'credit|cost|billing|usage' /workspace/mcp-eval/evals.md | head -40; cd /workspace/mcp-eval && python3 - <<'PY'
